package dev.droidmirror.companion

import org.json.JSONObject
import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertThrows
import org.junit.Test
import java.io.File

/** Interop proof: must match protocol/test-vectors.json, generated by Node (an independent implementation). */
class CryptoTest {
    private fun hex(s: String) = ByteArray(s.length / 2) { s.substring(it * 2, it * 2 + 2).toInt(16).toByte() }
    private fun hexString(b: ByteArray) = b.joinToString("") { "%02x".format(it) }

    private val vectors: JSONObject by lazy {
        // Unit tests run with the module directory (android/app) as working directory.
        JSONObject(File("../../protocol/test-vectors.json").readText())
    }
    private val secret get() = hex(vectors.getString("secret"))
    private val macSalt get() = hex(vectors.getString("macSalt"))
    private val phoneSalt get() = hex(vectors.getString("phoneSalt"))

    private fun frames() = (0 until vectors.getJSONArray("frames").length()).map { vectors.getJSONArray("frames").getJSONObject(it) }

    @Test fun keyDerivationMatchesNode() {
        val salt = macSalt + phoneSalt
        for (label in listOf("mac->phone", "phone->mac")) {
            assertEquals(vectors.getJSONObject("keys").getString(label), hexString(CompanionChannel.derive(secret, label, salt)))
        }
    }

    @Test fun sealMatchesNodeByteForByte() {
        val mac = CompanionChannel(secret, macSalt, phoneSalt, isPhone = false)
        val phone = CompanionChannel(secret, macSalt, phoneSalt, isPhone = true)
        for (f in frames()) {
            val channel = if (f.getString("label") == "mac->phone") mac else phone
            val sealed = channel.seal(f.getString("payload").toByteArray(), hex(f.getString("nonce")))
            assertEquals(f.getString("frame"), hexString(sealed))
        }
    }

    @Test fun opensNodeFrames() {
        val mac = CompanionChannel(secret, macSalt, phoneSalt, isPhone = false)
        val phone = CompanionChannel(secret, macSalt, phoneSalt, isPhone = true)
        for (f in frames()) {
            val frame = hex(f.getString("frame"))
            val body = frame.copyOfRange(4, frame.size)
            val opened = if (f.getString("label") == "mac->phone") phone.open(body) else mac.open(body)
            assertEquals(f.getString("payload"), String(opened))
        }
    }

    @Test fun rejectsReplayTamperAndWrongSession() {
        val mac = CompanionChannel(secret, macSalt, phoneSalt, isPhone = false)
        val phone = CompanionChannel(secret, macSalt, phoneSalt, isPhone = true)
        val frame = mac.seal("hello".toByteArray())
        val body = frame.copyOfRange(4, frame.size)
        assertArrayEquals("hello".toByteArray(), phone.open(body))
        assertThrows(CompanionCryptoException::class.java) { phone.open(body) }          // replay

        val tampered = mac.seal("x".toByteArray()).let { it.copyOfRange(4, it.size) }
        tampered[14] = (tampered[14].toInt() xor 1).toByte()
        assertThrows(CompanionCryptoException::class.java) { phone.open(tampered) }       // tamper

        val otherSession = CompanionChannel(secret, ByteArray(16) { 9 }, phoneSalt, isPhone = true)
        val b2 = mac.seal("y".toByteArray()).let { it.copyOfRange(4, it.size) }
        assertThrows(CompanionCryptoException::class.java) { otherSession.open(b2) }      // other session
    }
}
